export const THAI_AT_KNOWLEDGE_72 = "=== PAGE 1 ===\n1. Vòng Kỷ Dư Thái Ất Kể Năm \nDùng tích niên Thái Ất tức tích số có được tính từ năm Thượng cổ \nGiáp Tý đến năm cầu việc, đem chia 360, số dư < 360 là số toán vòng Kỷ \nDư năm cầu việc. \nCông thức: Tích niên Thái Ất của năm chia cho 360  = ... dư < 360 là vòng \nKỷ Dư.  \n \nVí dụ: tính vòng Kỷ Dư năm 2014 Giáp Ngọ. \nNăm Giáp Ngọ có số tích niên TháiẤt (TA) là 10.155.931 \nToán: 10.155.931 chia cho 360  = 28210 dư 331 < 360 \nKết luận năm 2014 Giáp Ngọ có vòng Kỷ Dư là 331. \n \n2. Vòng Kỷ Dư Thái Ất Kể Tháng \nDùng số tích tháng có được từ Thượng cổ Giáp Tý đến tháng cầu việc \nchịa 360, số dư < 360 là vòng Kỷ Dư tháng. Để rút gọn phép toán, trên \nthực tế người ta dùng vòng Kỷ Dư năm, của năm có tháng cầu việc trừ 1 \nrồi nhân 12, cộng thêm số tháng trong năm cầu việc, và cộng thêm với 2 \ntháng Thiên chính và Địa chính (theo cách gọi của Thái Ất thức tháng 11 \nlà Thiên chính, tháng 12 là Địa chính; tháng giêng là Nhân chính), kết quả \ncó được đem chia 360, số dư < 360 là số vòng Kỷ Dư tháng. \nVí dụ: tính vòng Kỷ Dư tháng 4 năm 2014 Giáp Ngọ \nNăm Giáp Ngọ có số vòng Kỷ Dư là 331. Thực hiện phép toán như \nsau: \nBước 1: (331 - 1) x 12 + 4 = 11 dư 4 +2 = 6.  \nTrong đó: \n 331 là vòng kỷ dư năm giáp ngọ 2014. \n\n=== PAGE 2 ===\n-1 là lùi về năm 2013. \nX12 là 12 tháng trong năm. \n+4 là cộng thêm 4 tháng đến tháng 4 là tháng cần lập sa bàn.  \nKết quả dư 4. Và cộng 2 là 2 tháng lùi về.( tháng 11, tháng 12 của năm \n2013) . vì lịch Thái Ất khởi đầu là tháng Giáp Tý, mà phép toán lại tính từ \ntháng giêng là tháng Dần nên phải cộng thêm 2 số toán của tháng 11 và \ntháng 12. Nên số toán bước 1 ví dụ trên tính được là 4 phải cộng thêm 2 \ntức 4 + 2 = 6 < 360.  \nKết luận: vòng Kỷ Dư tháng của tháng 4 năm 2014 Giáp Ngọ là 6 \n \n3. Vòng Kỷ Dư Thái Át Kể Ngày \nMột năm có 365 ngày sấp xỉ với 1 vòng kỷ 360, nên phép tính vòng Kỷ Dư \nngày được người xưa rút gọn bằng phép tính: tính từ ngày Giáp Tý đầu \ntiên sau tiết Đông chí của năm trước đến ngày cầu việc xem được bao \nnhiêu ngày, số toán đó chính là vòng Kỷ Dư của phép toán Kể ngày cần \ntoán. \n \nVí dụ: tính vòng Kỷ Dư của ngày 16 tháng 4 năm 2014 (âm lịch). \nTa có ngày Giáp Tý đầu tiên sau tiết Đông chí năm 2013 là ngày 22 tháng \n11. Tính từ ngày 22 tháng 11 năm 2013 đến ngày 16 tháng 4 năm 2014 là \n142 ngày. \nKết luận: vòng Kỳ Dư của ngày 16 tháng 4 năm 2014 là 142. \n \n4. Vòng Kỷ Dư Thái Ất Kể Giờ \nChỉ riêng phép Thái Ất kể giờ phân thành dương cục và âm cục: \n- Dương cục: tính từ ngày Giáp Tý đầu tiên sau tiết Đông chí năm trước \n\n=== PAGE 3 ===\nđến trước tiết Hạ chí của năm sau. \n- Âm cục: tính từ ngày Giáp Tý đầu tiên sau tiết Hạ chí đến trước tiết \nĐông chí. \nCách tính: thông thường đề rút gọn phép tính người xưa lấy ngày \nGiáp tý hay Giáp Ngọ gần nhất với ngày có giờ cầu việc, tính đến ngày \nđó được sốtích ngày là bao nhiêu đem trừ 1 nhân 12 sau cộng với số giờ \ntính từ giờ Tý của ngày cầu việc đến giờ cầu việc. Kết quả cho số toán \ncủa vòng Kỷ Dư giờ cần toán. \nVí dụ: cần tính vòng Kỷ Dư giờ Thìn của ngày 8 tháng 4 năm 2014. \nTa có ngày Giáp Tý gần nhất là ngày 24 tháng 3, tính từ ngày 24 \ntháng 3 đến ngày 8 tháng 4 được số tích ngày là 14. \nTa tính: (14 - 1 ) x 12 + 5 = 161 giờ \nKết luận: vòng Kỷ Dư Thái Ất Kể Giờ của giờ Thìn ngày 8 tháng 4 \nnăm 2014 là 161. \nCách tính vòng Kỷ Dư Thái Ất Kể Giờ của âm cục giống như cách tính \ncủa dương cục, cũng lấy ngày Giáp Tý hay Giáp Ngọ gần nhất ngày giờ \ntoán việc để toán. \nĐây là phép toán giản lược nhưng hoàn toàn chính xác. \n \nTOÁN PHÂN NGUYÊN - CỤC \nLịch Thái Ất đã nói rõ: \n1 vòng kỷ = 360 số toán \n1 vòng kỷ = 5 nguyên \n1 nguyên = 72 cục \nPhép phân nguyên định cục cho Tứ Kể đều chung lệ: \nCông thức toán: Vòng Kỷ Dư chia cho 72 = số thành & số dư \n\n=== PAGE 4 ===\nTrong đó: Số thành là số nguyên, số dư là số cục. \nVí dụ: phân nguyên định cục năm 2014 - Giáp Ngọ có vòng Kỷ Dư \nnăm là 331. \nTính: Vòng Kỷ Dư chia cho 72 => 331 : 72 = 4 dư 43 . Trong đó , 4 là \nnguyên, 43 là cục.  \nKết luận: năm 2014 Giáp Ngọ thuộc nguyên 5 cục 43. \n \nKế giờ \nPhép tính cửa trực sự cho Kể giờ cũng chung quy tắc trên, tuy nhiên con \nsố giờ toán được sẽ rất lớn, lại định theo âm cục và dương cục. Nên cách \ntốt nhất là làm toán rút gọn theo cách thức sau: \n- Dương cục sau tiết Đông chí lấy ngày Giáp Tý hay Giáp Ngọ gần nhất \ntính từ Giáp Tý của ngày ấy đến giờ cầu việc xem số tích giờ được bao \nnhiêu. Đem chia cho 240. Số dư nhỏ hơn < 240 lại đem chia cho 30. để \ntìm cửa trực sự. \n- Âm cục sau tiết Hạ chí lấy ngày Giáp Tý, hay Giáp Ngọ gần nhất, tính từ \ngiờ Giáp Tý đến giờ cầu việc xem cố tích giờ được bao nhiêu, cách tính \ntoán tiếp theo cũng giống như cách tính cho dương cục. \n \n \nLưa ý: Chu kỳ của Bát môn (8 cửa) là 240 số toán, tại mỗi cửa ứng với 30 \nsố toán. Nên phép toán vào cửa trực sự của Tứ kể cũng còn nhiều cách \ntính toán rút gọn khác nhau. \nVí dụ: Cách tính rút gọn trong Kể giờ Trương Lương đã viết lại như \nsau: \n• Sau tiết Đông chí dương độn \n\n=== PAGE 5 ===\n- Ngày Giáp Của Khai bắt đầu làm cửa trực sự từ giờ Tý lúc nửa đêm. \n- Ngày Bính cửa Sinh bắt đầu làm cửa trực sự vào giờ Ngọ giữa trưa. \n- Ngày Kỷ cửa Kinh bắt đầu làm cửa trực sự vào giờ Tý lúc nửa đêm. \n- Ngày Tân cửa Hưu bắt đầu làm cửa trực sự vào giờ Ngọ giữa trưa. \n• Sau tiết Hạ chí dương độn \n- Ngày Giáp cửa Đỗ bắt đầu làm cửa trực sự từ giờ Tý lúc nửa đêm. \n- Ngày Bính cửa Tử bắt đầu làm cửa trực sự vào giờ Ngọ giữa trưa, \n- Ngày Kỷ cửa Thương bắt đầu làm cửa trực sự vào giờ Tý lúc nửa đêm. \n- Ngày Tân cửa Cảnh bắt đầu làm cửa trực sự vào giờ Ngọ giữa trưa. \nTừ đó dễ dàng suy ra - Dương cục lấy cửa Khai - Sinh - Kinh - Hưu \nlàm trực sự. \n- Âm cục lấy cửa Đỗ - Tử -Thương - Cảnh làm trực sự. \n \n(Quy luật vận hành \n9 cung Thái Ât gồm: Kiền - Ly - Cấn - Chấn - Trung cung - Đoài \n- Khôn - Khảm - Tốn. Thái Ất vận hành qua 8 cung chính, không vào \nTrung cung (5). Thời gian đóng tại mỗi cung ứng với 3 số toán. Vòng tiểu \nchu kỳ là 24 số toán (8x3=24). \nThứ tự vận hành như sau: \n- Dương độn (dùng chung cho Tứ Kể): Thái Ất khởi từ cung Kiền thuận \nhành theo thứ tự Kiền (1) - Ly (2) - Cần (3) - Chấn (4) - Trung cung (5 \nkhông vào) - Đoài (6) - Khôn (7) - Khảm (8) - Tốn (9). \n- Âm độn (dùng riêng cho Kể giờ từ tiết Hạ chí đến trước tiết Đông chí): \nThái Ât khởi từ cung Tốn nghịch hành theo thứ tự Tốn (9) - Khảm \n(8) - Khôn (7) - Đoài (6) - Trung cung (5 không vào) - Chấn (4) - Cần \n(3) - Ly (2) - Kiền (1). \n\n=== PAGE 6 ===\nc) Toán pháp an sao \nCách toán: dùng vòng Kỷ Dư chia cho 24, số dư < 24 lại chia tiếp cho 3, \nkết quả số thành là số cung Thái Ất đã vận hành qua, số dư là thời gian \nđã vào đóng tại cung sở tại. \n50 \nKhảo cứu & Biên soạn: Nguyễn Vân Liên \n- GIẢI MÃ THÁI ÁT \nVí dụ: tính và an sao Thái Át năm 2014 - Giáp Ngọ. Tích niên Thái \nÁt là 10.155.931, vòng Kỳ Dư là 331 \nBước 1: lấy 331 : 24 = .... dư 19 < 24 \nBước 2: lấy \n19 : 3 = 6 du 1 \nKết luận: năm 2014 - Giáp Ngọ, Thái Ất đã kinh hành qua 6 cung, nay đã \nvào đóng ở cung thứ 7 được 1 năm. Theo thứ tự thuận hành khởi từ cung \nKiền (1) thì Thái Ất đóng tại cung Khảm (8). \n \nCách tính Văn Xương \nb) Quy luật vận hành \nVăn Xương vận hành luân lưu qua 16 thần cung Thái Ât, tiểu chu kỳ \nlà 18 số toán. \n- Dương độn: Văn Xương khởi từ cung Thân tức cung Vũ Đức chuyển \nthuận xuôi 16 cung thần, nếu gặp cung Kiền - Khôn thì lưu 2 số toán còn \ncác cung khác lưu 1 số toán. \n- Âm độn: Văn Xương khởi từ cung Dần tức cung Lã Thân, cũng chuyển \nthuận qua 16 cung thần, nếu gặp cung Cấn - Tốn thì lưu 2 số toán còn \ncác cung khác lưu 1 số toán. \n\n=== PAGE 7 ===\nc) Toán pháp an sao \nCách toán: dùng vòng Kỷ Dư chia 18, số dư < 18 dùng để an sao. \nVí dụ: tính và an sao Văn Xương năm 2014 - Giáp Ngọ, có vòng Kỷ \nDư 331 \n \n \nBước 1: lấy 331 : 18 = ... dư 7 < 18 \nBước 2 an sao: theo thứ tự dương độn khởi từ cung Thân thuận hành \nthì vìa đúng cung Tý (Khám) là đủ 7 số toán. \nKết luận: năm 2014 - Giáp Ngọ, Văn Xương đóng tại cung Khảm \n(Tý). \n \nThủy Kích (Địa Mục - Khách Mục) - Ngũ hành Hỏa \na) Biểu tượng và nghĩa lý \nThủy Kích còn gọi là Địa Mục - Khách Mục, là phụ tướng của Thái Át, là \nKhách Mục của Kể Thần, nắm quyền chinh phạt, điều động binh quyền. \nThùy Kích tới phận dã nào là ở đó có họa biến, dân chúng lưu vong, loạn \nlạc. \nb) Quy luật vận hành \nThủy Kích vận hành luân lưu qua 16 cung thần vị. Muốn tính được ngôi vị \ncủa Thủy Kích cần toán được ngôi vị của Kể Thần và Văn Xương. \nĐếm từ ngôi Kể Thần đến ngôi của Văn Xương xem được bao nhiêu ngôi. \nLại khởi từ cung Cấn thuận theo 16 cung thần vừa đủ số ngôi đă toán \nđược thì an Thủy Kích. Âm và dương độn có cách tính và an sao giống \nnhau. \nVí dụ: tính và an sao Thủy Kích năm 2014 - Giáp Ngọ. \n\n=== PAGE 8 ===\nTa tính được Văn Xương đóng tại cung Tý, Kể Thần đóng tại cung Thân, \ntừ cung Thân đến cung Tý đếm được 6 ngôi, lại khởi từ cung Cấn đến \ncung Tị là vừa đủ 6 ngôi. \nKết luận: Thủy Kích năm 2014 - Giáp Ngọ đóng tại cung Tị. \n \nKế Thần - Ngũ hành Hỏa \na) Biểu tượng và nghĩa lý \nKể Thần là thiên sứ thuộc chủ (ẩn tinh), là vị Thần độ lượng thẩm sát \n \ntrời đất, con người và vạn vật, phân biệt rõ thị phi. \nb) Quy luật vận hành \nKể Thần kinh hành qua 12 cung Chi thần, tiểu chu kỳ là 12 số toán. \n- Khối dương khởi từ cung Dần nghịch hành qua 12 Chí thần: Dần \n- Sửu - Tý - Hợi - Tuất - Dậu - Thân - Mùi - Ngọ - Tị - Thìn - Mão. \n- Khối âm khởi từ cung Thân cũng chuyển nghịch qua 12 Chi thần: \nThân - Mùi - Ngo - Tị - Thìn - Mão - Dần - Sửu - Tý - Hợi - Tuất - Dậu. \nc) Cách toán \nDùng vòng Kỷ Dư chia 12, số dư < 12 dùng để an Kể Thần. \nVí dụ: tính và an sao Kể Thần năm 2014 - Giáp Ngọ, vòng Kỷ Dư 331. \nBước 1: lấy 331 : 12 =... dư 7 < 12 \nBước 2: an sao khởi từ cung Dần nghịch theo thứ tự đến cung Thân \nlà vừa đủ 7 số toán. \nKết luận: năm 2014 - Giáp Ngọ, Kể Thần đóng tại cung Thân. \n \nKế Định - Ngũ hành Hóa \na) Biểu tượng và nghĩa lý \n\n=== PAGE 9 ===\nKể Định là thiên sứ thuộc khách (ẩn tinh). Kinh viết: \"Khi xưa Thái Khương \nCông dụng phép toán này để trợ khách, về sau Trương Lương được \nphép đó mà phò giúp nhà Hán. Phép Kể Định được dùng đo độ số u \nminh của Thái Ât nhưng càng về sau thì càng sai lạc, không thể lấy lý mà \nsuy được nữa. Kể Định sinh ra Toán Định, nay chỉ thấy con số của phép \ntoán này trong \"Tam Tài toán pháp\". \nb) Cách tính \nĐếm từ cung Thần hợp tới cung Văn Xương xem được bao nhiêungôi, rồi \nkhởi từ cung Thái Tuế thuận hành 16 cung thần Thái Ất, vừa hết số ngôi \nđã đếm được thì an Kể Định. \nVí dụ: tính và an sao Kể Định năm 2014 - Giáp Ngọ. Năm Giáp Ngọ Thái \nTuế ở cung Ngọ, Thần Hợp ở cung Mùi, Văn Xương ở cung Tý. Từ cung \nMùi đến cung Tý đếm được 8 ngôi. Lại đem khởi từ cung Thái Tuế (tức \ncung Ngọ) đếm đến cung Hợi là vừa đủ 8 ngôi. \nKết luận: năm 2014 - Giáp Ngọ, Kể Định đóng tại cung Hợi. \nc) Số toán định \nNhư mục (a) đã nêu Kể Định sinh Toán Định, nay toán định tính như sau: \ntính từ ngôi Kể Định đến ngôi giáp Thái Ất xem được bao nhiêu số toán. \nĐó chính là số Toán Định. Nên nhớ nếu Kể Định đóng ở cung chính thì số \ntoán là biệt số của cung, nếu ở cung gián thần thì được tính 1 số toán, \ncác cung gián khác không tính. \nVí dụ: tính số toán của Kể Định năm 2014 - Giáp Ngọ. \nKể Định tại cung Hợi là giáp cung Thái Ất được tính 1 toán. Vậy số \nToán Định là 1. \n \nĐại Tướng Chủ - Ngũ hành Kim \n\n=== PAGE 10 ===\na) Biểu tượng và nghĩa lý \nĐại Tướng Chủ là vị Thần Tướng chủ về chiến tranh và chinh phạt. \nĐại Tướng Chủ sinh ra Toán Chủ. \nb) Toán chủ \nĐếm từ cung Văn Xương đến cung giáp Thái Ất xem được bao nhiêu số \ntoán, đó chính là số toán chủ. Nên nhớ: trường hợp Văn Xương đóng ở \ncung chính thì lấy theo biệt số cung, ở cung gián thần thì tính 1 số toán, \ncác cung gián khác không tính. \nVí dụ: tìm số Toán Chủ năm 2014 - Giáp Ngọ. \n \nVăn Xương đóng ở cung Khảm (8), Thái Ất cũng đóng ở cung Khảm \n(8). Vậy Toán Chủ là 8. \nc) Phép an sao Đại Tướng Chủ \nCăn cứ vào số Toán Chủ để an sao cho Đại Tướng Chủ. \n- Nếu số Toán Chủ ở hàng đơn vị thì an Đại Tướng Chủ vào các cung có \nphối biệt số tương ứng. \nVí dụ: số Toán Chủ là 8 thì Đại Tướng chủ được an vào cung Khảm (8) \n- Nếu số toán > 10, 20, 30 thì bỏ hàng chục chỉ lấy hàng đơn vị để \nan sao \nVí dụ: Toán Chủ là 16 thì an Đại Tướng Chủ vào cung Đoài (6). \n \nTham Tướng Chủ - Ngũ hành Thủy \na) Biểu tượng và nghĩa lý \nTham Tướng Chủ là Phụ Tướng và là trợ thủ đắc lực của Đại Tướng \nChủ. Ngũ hành thuộc Thủy ứng với Bắc phương. \nb) Cách tính \n\n=== PAGE 11 ===\nDùng biệt số cung của Đại Tướng Chủ nhân 3, số thành có được lấy \nsố hàng đơn vị để an sao Tham Tướng Chủ. Nên nhớ: \n- Nếu số toán của Tham Tướng Chủ ở hàng đơn vị thì an Tham Tướng \nChủ vào cung nào có biệt số tương ứng. \n- Nếu số toán > 10, 20, 30 thì bỏ hàng chục lấy hàng đơn vị để an sao. \nVí dụ: năm 2014 Giáp Ngọ, Đại Tướng Chủ có biệt số 8. \nLấy 8 x 3 = 24, kết quả số toán của Tham Tướng Chủ > 20, bỏ 20 \nlấy 4. \nVậy Tham Tướng Chủ được an vào cung 4 (Chấn). \n \n8. Đại Tướng Khách - Ngũ hành Thủy \na) Biểu tượng và nghĩa lý \nĐại Tướng Khách là thủy thần được khí của Thủy Đức. Về vị trí là chú ở \nphương Bắc, ứng với mùa đông, là vị thần chủ về chiến tranh và chinh \nphạt. Đại Tướng Khách sinh ra Toán Khách. \nb) Toán khách \nĐềm từ cung Thủy Kích đến ngôi giáp Thái Ât xem được bao nhiêu số \ntoán, đó chính là Toán Khách. Nếu Thủy Kích đóng ở chính cung thì tính \nbiệt số của cung, nếu ở các cung gián thần thì tính 1 số toán còn các \ncung gián khác không tính. \nVí dụ: tìm Toán Khách cho năm 2014 - Giáp Ngọ. \nNăm 2014, Thủy Kích đóng tại cung Tị, Thái Ất đóng tại cung Khảm. Đếm \ntheo thứ tự đề tính số: Tị (I) - Ly (2) - Khôn (7) - Đoài \n(6) - Kiền (1), số toán cộng lại được 17. Vậy số Toán Khách năm \n2014 - Giáp Ngọ là 17. \nc) Phép an sao Đại Tướng Khách \n\n=== PAGE 12 ===\nCăn cứ vào số Toán Khách để an sao cho Đại Tướng Khách. Cách \ntính cũng giống như phép an sao của Đại Tướng Chủ. \n9. Tham Tướng Khách - Ngũ hành Mộc \na) Biểu tượng và nghĩa lý \nTham Tướng Khách là phụ Tướng, là trợ thủ đắc lực của Đại Tướng \nKhách, Ngũ hàng Mộc ứng với phương Đông. \nb) Cách tính và an sao \nCách tính và an sao Tham Tướng Khách cũng giống như phép tính. \nan sao của Tham Tướng Chủ. \n \nNgũ Phúc - Ngũ hành Thổ \n \na) Biểu trợng và nghĩa lý \nThần tinh Ngũ Phúc là vị Thần ban phúc, đến phận dã nào thì ban ân \nbố đức ở đó. \nb) Quy luật vận hành \nNgũ Phúc kinh hành qua 5 cung chính của Thái Ất là 4 cung ở tứ duy \n(Kiền - Cần - Tốn - Khôn) và Trung cung. Thời gian đóng tại mỗi cung là \n45 số toán, một vòng chu kỳ là 225 số toán (5 x 45 = 225). Ngũ Phúc khởi \nthuận theo thứ tự: Kiền - Cấn - Tốn - Khôn - Trung cung. \nc) Cách tính \nCách 1: dùng tích niên Trung cổ Giáp Dần của năm cầu việc chia 225, số \ndư < 225 lại chia tiếp 45. Kết quả số thành là số cung Ngũ Phúc đã vận \nhành qua, số dư là thời gian đã vào đóng ở cung sở tại. \nCách 2: dùng tích niên Thái Ất của năm cầu việc cộng thêm số doanh \nsai là 125, kết quả có được thực hiện phép toán như cách 1. \n\n=== PAGE 13 ===\nVí dụ: năm 2014 - Giáp Ngọ có tích niên Trung cổ Giáp Dần là 14.621 \nBước 1: lấy 14.621 : 225 = ... dư 221 \nBước 2: lấy \n221 : 45 =4 dư 41 \nNhư vậy Ngũ Phúc đã qua 4 cung, hiện đã vào cung thứ 5 được 41 năm. \nTheo thứ tự vận hành thì Ngũ Phúc đang ở Trung cung (5) \n \n \n4. Quân Cơ - Ngũ hành Thổ \na) Biểu tượng và nghĩa lý \nQuân Cơ là vị Thần tinh ở Tòa Tử Vi viên, còn được gọi là Tử Vi Đại Đế, là \nchủ tôn của các vị Thần tinh, nắm giữ đại quyền, tuần sát 4 phương, an \ndân, trị quốc, cai quản cả trời đất và nhân gian vạn vật. \nb) Quy luật vận hành \n \nMột vòng chu kỳ của Quân Cơ vừa tròn 360 số toán. Quân Cơ khởi từ \ncung Ngọ thuận hành theo 12 Chi thần, tại mỗi cung đóng 30 số toán (12 \nx 30= 360). \nc) Cách tính \n- Cách 1: dùng tích niên Trung cổ Giáp Dần của năm cầu việc chia 360, \nsố dư < 360 lại chia tiếp 30. Kết quả số thành là số cung Quân Cơ đã vận \nhành qua, số dư là thời gian đã vào đóng ở cung sở tại. \n- Cách 2: dùng tích niên Thái Ất của năm cầu việc cộng thêm số doanh \nsai 250, kết quả thu được chia 360, số dư < 360 lại chia tiếp 30. \nKết quả số thành là số cung Quân Cơ đã vận hành qua, số dư là thời gian \nQuân Cơ đã vào đóng ở cung sở tại. \n\n=== PAGE 14 ===\nCũng có thể dùng ngay vòng Kỷ Dư của năm cần toán việc cộng với số \ndoanh sai 250 rồi chia tiếp 30. Kết quả số thành và số dư như trên. \nVí dụ: tính Quân Cơ của năm 2014 - Giáp Ngọ có tích Trung Cổ \nGiáp Dần 14.621. \nBước 1: 14.621 : 360 = 40 dư 221 \nBước 2: 221 : 30 \n= 7 dư 11 \nTheo thứ tự vận hành của Quân Cơ khởi từ cung Ngọ đến cung Tý vừa \nđủ 7 số toán, số 11 dư là thời gian Quân Cơ đã vào cung Sửu được11 \nnăm. \nKết luận: năm 2014 Quân Cơ đóng tại cung Sửu. \n \nThần Cơ - Ngũ hành Thổ \na) Biểu tượng và nghĩa lý \nThần Cơ nằm trong Tòa Tử Vi viên, phụ tá cho Thiên Đế, cai quản lục \ncung, quản 28 tú, nắm quyền uy đức, xoay chuyển tạo hóa, phù trên trị \ndưới, văn võ kiêm toàn. \nb) Quy luật vận hành \n \n \nThần Cơ khởi từ cung Ngọ thuận theo thứ tự 12 Chi thần. Một vòng \ntiểu chu kỳ là 36 số toán, mỗi cung đóng 3 số toán. \nc) Cách tính \n- Cách 1: dùng tích Trung cổ Giáp Dần của năm cầu việc chia 360, số dư \n< 360 chia tiếp 36, số dư < 36 lại chia tiếp 3. Kết quả số thành là số cung \nThần Cơ đã vận hành qua, số dư < 3 là thời gian Thần Cơ đã vào đóng ở \n\n=== PAGE 15 ===\ncung sở tại. \nVí dụ: năm 2014 - Giáp Ngọ, tích Trung cổ Giáp Dần là 14.621. \nBước 1: lấy \n14.621 : 360 = 40 dư 221 \nBước 2: lấy \n221 :36= 6 dư 5 \nBước 3: lấy \n5 : 3 = 1 dư 2 \nKết luận: năm 2014 - Giáp Ngọ, Thần Cơ đã vào đóng tại cung Mùi \nđược 2 năm.  \nCách 2 : dùng tích niên Thái Ất hoặc dùng vòng kỷ dư của năm lập sa \nbàn cộng thêm với số doanh sai 250 rồi lấy tổng này chia cho 360 , lấy số \ndư chia tiếp cho 36 , được số dư lại chia tiếp cho 3. Kết quả số cũng \nđúng như cách 1. \n \nDân Cơ - Ngũ hành Thổ \na) Biểu tượng và nghĩa lý \nDân Cơ là Thần tài phú, cai quản kho lẫm, giàu lòng nhân đức. Dân \nCơ đại diện cho dân, đến phận dã nào an lòng bách tính ở đó. \nb) Quy luật vận hành \nDân Cơ khởi từ cung Tuất thuận hành theo 12 Chi thần. Tiểu chu kỳ \nlà 12 số toán, thời gian đóng tại mỗi cung là 1 số toán. \nc) Cách tính \n- Cách 1: dùng tích niên Trung cổ Giáp Dần của năm cầu việc chia 360, \nsố dư < 360 chia tiếp 12, số dư < 12 dùng để an sao. \nVí dụ: năm 2014 - Giáp Ngọ, có tích niên Trung cổ Giáp Dần là \n\n=== PAGE 16 ===\n14.621. Bước 1: lấy 14.621 : 360 = 40 dư 221 \nBước 2: lấy \n221:12 \n= 18 du 5 \nBước 3: an sao, 5 là số dư < 12 dùng để an sao Dân Cơ, theo thứ tự \nkhởi từ cung Tuất đến cung Dần là vừa đủ 5 số toán. \nKết luận: năm 2014 - Giáp Ngọ, Dân Cơ đóng tại cung Dần. \n- Cách 2: dùng tích niên Thái Ất hay dùng vòng Kỷ Dư của năm cầu việc \ncộng với số doanh sai 250 rồi chia cho 360, số dư < 360 lại chia tiếp \n12. Kết quả số dư < 12 dùng để an sao. \nVí dụ: năm 2017 - Đinh Dậu có vòng Ký Dư 334. Bước 1: lấy (334 \n+250) : 360 = 224 \nBước 2: lấy \n224 : 12 \n= 18 dư 8 \nBước 3: an sao, khởi từ cung Tuất thuận theo 12 Chi thần đến cung \nTị là vừa đủ 8 số toán. \nKết luận: năm 2017 - Đinh Dậu, Dân Cơ đóng tại cung Tị. \n \nTứ Thần - Ngũ hành Thủy \na) Biểu tượng và nghĩa lý \nTứ Thần vốn là Nguyên Thần của thủy khí thiên địa, tính chất nửa cát nửa \nhung, là Thần cai quản mưa gió và lũ lụt hạn hán, chuyển \nbiến họa phúc. \nb) Quy luật vận hành \nVòng chu kỳ của Tứ Thần là 36 số toán, vận hành qua 12 cung (gồm 9 \n\n=== PAGE 17 ===\ncung chính Thái Ất và 3 cung Chi thần là Dần, Thân, Tị), tại mỗi cung \nđóng 3 số toán. Tứ Thần khởi theo thứ tự: Kiền - Ly - Cấn - Chấn - Trung \nảo cứu&Biên Soạn: Nguyễn Vân Liên \n61 \n( GIẢI MÃ THÁI ÁT \ncung - Đoài - Khôn - Khảm - Tốn - Tị - Thân - Dần. \nLưu ý: Tại cung Tị gọi là Giáng cung, Tại cung Thân gọi là Minh Đường, Tại \ncung Dần gọi là Ngọc Đường. \nQuy ước này được dùng chung cho cả bộ sao \"Tứ Thần\" gồm 4 sao: \nTứ Thần, Thiên Át, Trực Phù, Địa Ất. \nc) Cách tính \nDùng vòng Kỷ Dư toán được của thời điểm cầu việc chia 36, số dư < 36 \nchia tiếp cho 3. Kết quả, số thành là số cung Tứ Thần đã vận hành qua, \nsố dư < 3 là thời gian Tứ Thần đã vào đóng ở cung sở tại. \nVí dụ: năm 2014 - Giáp Ngọ, vòng Kỷ Dư là 331. Bước 1: lấy 331 : \n36 = 9 du 7 \nBước 2: lấy \n7: \n3=2 dư 1 \nBước 3: an sao, theo thứ tự khởi từ cung Kiền thuận đến cung Cấn là \nvừa đủ 3 số toán. \nKết luận: năm 2014 - Giáp Ngọ, Tứ Thần đóng tại cung Cấn. \n \nĐại Du - Ngũ hành Kim \n() Biểu tượng và nghĩa lý \nĐại Du là hung thần trong trời đất, khí phối Kim Thần, là vị Thần hung sát \n\n=== PAGE 18 ===\nvà tàn phá. Đại Du đến phận dã nào thì ở đó thiên vận thất thường, mùa \nmàng thất thu, chính lệnh mê muội, chiến loạn liên miên. \nb) Quy luật vận hành \nĐại Du kinh hành qua 8 cung chính của Thái Ât (không vào Trung cung \n5), khởi từ cung Khôn theo thứ tự: Khôn - Khảm - Tôn - Kiên - Ly \n- Cấn - Chấn - Đoài. Thời gian đóng tại mỗi cung là 36 năm, trong đó 12 \nnăm hành theo lý thiên, 12 năm hành theo lý địa, 12 năm hành theo lý \nnhân. Vòng chu kỳ là 228 năm (8 x 36 = 288). \nc) Cách tính \n- Cách 1: dùng tích Trung cổ Giáp Dần của năm cầu việc chia 288, số dư \n< 288 chia tiếp 36. Kết quá số thành là số cung Đại Du đã vận hành qua, \nsố dư là thời gian đã vào đóng ở cung sở tại. \nVí dụ: năm 2014 - Giáp Ngọ có tích Trung Cổ Giáp Dần là 14.621: \nBước 1: lấy 14.621 : 288 = 5 dư 221 \nBước 2: lấy 221 : 36 = 6 dư 5 \nKết luận: Đại Du đã qua 6 cung, nay đã vào cung thứ 7 được 5 năm, theo \nthứ tự khởi từ cung Khôn đến cung Chấn là vừa đủ 7 số toán. Vậy Đại Du \nnăm 2014 đóng tại cung Chấn. \n- Cách 2: dùng tích niên Thái Ất của năm cầu việc cộng thêm số doanh \nsai +34, kết quả có được chia 2.880, lấy số dư chia tiếp 288, số dư < 288 \nlại chia tiếp 36. Kết quả có được dùng để an sao. \nVí dụ: năm 2014 - Giáp Ngọ, tích niên Thái Ất là 10.155.931 Bước \n1: lấy (10.155.931 + 34) : 2.880 = ... dư 1.085 \nBước 2: lấy 1.085 : 288 = 3 dư 221 \nBước 3: lấy \n221 : 36 = 6 dư 5 \n\n=== PAGE 19 ===\nKết quá giống cách tính 1. \n \nPhi Phù Thái Ất - Ngũ hành Hỏa \na) Biểu tượng và nghĩa lý \nPhi Phù còn có tên là Sao lửa, Bùa bay thuộc loại tuệ tinh - hung tinh, \nbiến hóa theo Ngũ hành, thường ở phương vị xung chiếu với \nThái Ất. \n \nQua một thời gian dài nghiên cứu Tam Thức nói chung và Thái Át tisức \nnói riêng, nay chúng tôi đã lập thành toán pháp chính xác để vận dụng \ncho phép tính Phi Phù. \n* Nhận xót: \n- Dương độn thì Phi Phù khởi từ cung Tốn theo thứ tự: Tốn - Tốn - Khôn - \nKiền - Kiền - Ly - Cấn - Chấn - Trung cung - Đoài - Khôn -Khảm. \nTại mỗi cung thời gian Phi Phù đóng ứng 3 số toán (12 x 3 = 36). \n- Âm độn thì Phi Phù khởi từ cung Kiền theo thứ tự: Kiền - Kiền - Khôn - \nTốn - Tốn - Khám - Khôn - Đoài - Trung cung - Chấn - Cấn - Ly. \nTại mỗi cung thời gian Phi Phù đóng ứng với 3 số toán (12 x 3 = 36). \n* Như vậy có thể nhận thấy: \nMột vòng chu kỳ của Phi Phù là 36 sô toán, tương đương 36 cục Phi Phù \nvận hành qua 9 cung chính của Thái Át, tại các cung Tốn -Khôn \n- Kiền đóng 6 số toán, các cung khác như Ly - Cần - Chấn -Trung cung - \nĐoài - Khảm đóng 3 số toán (3 x 6) + (6 x 3) = 36. • \nDương cục và âm cục cũng vậy chỉ khác khởi điểm mà thôi. * *Cách \ntính \nCăn cứ vào số của cục để toán như sau: \n\n=== PAGE 20 ===\nBước 1: dùng vòng Ký Dư có được chia 72, kết quả có được số thành \nlà số nguyên, số dư là số cục. \nBước 2: dùng số cục chia tiếp 3, kết quả số thành là số cung Phi Phù \nđã qua, số dư là thời gian đã vào đóng tại cung sở tại, \nBước 3: an sao, \n- Dương độn khởi từ cung Tốn theo thứ tự: Tốn - Tốn - Khôn - Kiền - Kiền \n- Ly - Cấn - Chấn - Trung cung - Đoài - Khôn - Khảm. \nÂm độn khởi từ cung Kiền theo thứ tự: Kiền - Kiền - Khôn - Tốn \n- Tốn - Khảm - Khôn - Đoài - Trung cung - Chấn - Cần - Ly. \nVí dụ: năm 2014 - Giáp Ngọ, vòng Kỷ Dư là 331. \nBước 1: lấy 331 : 72 = 4 dư 43, vậy là năm 2014 - Giáp Ngọ thuộc \nnguyên 5 - cục 43 \nBước 2: lấy 43 : 3 = 14 dư 1 \nBước 3: vì một vòng chu kỳ tương ứng với 12 cung nên kết quả 14 > 12, \nlấy 14 - 12 = 2 cung, thời gian dư 1 ở trên tương ứng với \n1/3 cung. \nKết luận: năm 2014 - Giáp Ngọ, Phi Phù vào cung thứ 3 đã được 1 \nnăm. Theo thứ tự thì Phi Phù đóng tại cung Khôn (7). \n \nThiên Tôn \na) Chu kỳ kinh hành \nTiểu chu kỳ của Thiên Tôn Thái Át là 4 số toán, kinh hành qua 4 cung \nchính: Tư - Ngọ - Mão - Dậu. Mỗi cung đóng 1 năm, thời gian đóng tại \nmỗi cung ăn 1 số toán. \n- Từ Đông chí đến Hạ chí (dương cục) khởi thứ tự: Khảm (8) -Đoài \n(6) - Ly (2) - Chân (4). \n\n=== PAGE 21 ===\n- Từ Hạ chí đến Đông chí (âm cục) khởi thứ tự: Chấn (4) - Ly (2) - Đoài (6) \n- Khảm (8). \n \nb) Cách toán an sao \nDùng vòng Kỷ Dư chia 4, số dư < 4 dùng để an sao. \nc) Ví dụ: tính và an sao Thiên Tôn năm 2014 - Giáp Ngọ. \nTa đã có vòng Kỷ Dư năm 2014 là 331. Lấy 331 : 4 = 82 dư 3 Như vậy năm \n2014, theo thứ tự kinh hành thì Thiên Tôn đóng ở cung \nthứ 3 là cung Ly (2). \n3. Thiên Hoàng \na) Chu kỳ kinh hành \nTiểu chu kỳ của Thiên Hoàng Thái Ất là 20 số toán, kinh hành qua 16 \ncung thần, gặp 4 cung ở tứ duy: Kiền - Khôn - Tốn - Cần thì lưu 2 số \ntoán, còn 12 cung gián thần khác mỗi cung lưu 1 số toán. \n- Dương cục khởi từ cung Thân thuận hành theo thứ tự: Thân - Dậu \n- Tuất - Kiền - Kiền - Hợi - Tý - Sửu - Cấn - Cấn - Dần - Mão - Thìn \n- Tốn - Tốn - Tị - Ngọ - Mùi - Khôn - Khôn. \n- Âm cục khởi từ cung Dần nghịch hành theo thứ tự: Dần - Cấn - Cấn \n- Sửu - Tý - Hợi - Kiền - Kiền - Tuất - Dậu - Thân - Khôn -Khôn - Mùi - \nNgọ - Tị - Tốn - Tốn - Thìn - Mão, \nb) Cách toán an sao \nDùng vòng Kỷ Dư chia 20, số dư < 20 dùng để an sao. \nc) Ví dụ: tính và an sao Thiên Hoàng năm 2014 - Giáp Ngọ. \nTa đã có vòng Kỷ Dư năm 2014 là 331. Lấy 331 : 20 = 16 dư 11 Như vậy \nnăm 2014, theo thứ tự kinh hành của dương cục khởi từ \ncung Thân thuận hành thì Thiên Hoàng đóng ở cung Dần. \n\n=== PAGE 22 ===\n \nThiên thời \nTiểu chu kỳ của Thiên Thời Thái Ất là 12 số toán, kinh hành qua 12 \nChi Thần, thời gian đóng tại mỗi cung ăn 1 số toán. \n- Dương cục khởi từ cung Dần (Lã thân), thuận hành qua 12 Chi Thần: \nDần - Mão - Thìn - Tị - Ngọ - Mùi - Thân - Dậu - Tuất - Hợi \n- Tý - Sửu. \n- Âm cục khởi từ cung Thân (Đại Vũ), nghịch hành qua 12 Chi Thần: \nThân - Mùi - Ngọ - Tị - Thìn - Mão - Dần - Sửu - Tý -Hợi - Tuất - Dậu. \nb) Cách toán an sao \nDùng vòng Kỷ dư chia 12, số dư < 12 dùng đề an sao. \nc) Ví dụ: tính và an sao Thiên Tôn năm 2014 - Giáp Ngọ. \nTa đã có vòng Kỷ Dư năm 2014 là 331. Lấy 331 : 12 = 27 dư 7 Như vậy năm \n2014, theo thứ tự kinh hành của dương cục khởi từ \ncung Dần thuận hành thì Thiên Thời đóng ở cung Thân. \n \nĐế Phù \na) Chu kỳ kinh hành \nTiểu chu kỳ của Đế Phù Thái Ất là 20 số toán, kinh hành qua 16 cung \nthần, gặp 4 cung Tý (Khảm) - Ngọ (Ly) - Mão (Chấn) - Dậu (Đoài) thì lưu \n2 số toán, còn 12 cung gián thần khác mỗi cung lưu 1 số toán. \n- Dương cục khởi từ cung Tuất, thuận hành theo thứ tự: Tuất - Kiền \n- Hợi - Tý - Tý - Sửu - Cấn - Dần - Mão - Mão - Thìn - Tốn - Tị - Ngọ - \nNgọ - Mùi - Khôn - Thân - Dậu - Dậu. \n- Âm cục khởi từ cung Thìn, nghịch hành theo thứ tự: Thìn - Mão - Mão - \nDần - Cấn - Sửu - Tý - Tý - Hợi - Kiền - Tuất - Dậu - Dậu \n\n=== PAGE 23 ===\n- Thân - Khôn - Mùi - Ngọ - Ngọ - Tị - Tốn. \nb) Cách toán an sao . \nDùng vòng Kỳ Dư chia 20, số dư < 20 dùng để an sao. \nc) Ví dụ: tính và an sao Đế Phù năm 2014 - Giáp Ngọ. \nTa đã có vòng Kỳ Dư năm 2014 là 331. Lây 331 : 20 = 16 dư 11 Như vậy \nnăm 2014, theo thứ tự kinh hành của dương cục khởi từ \ncung Tuất thuận hành thì Đế Phù đóng ở cung Thìn. \n \nPhi Điểu \na) Chu kỳ kinh hành \nTiểu chu kỳ của Phi Điểu Thái Ất là 9 số toán, kinh hành qua 9 cung chính \ncủa Thái Ất. Mỗi cung đóng 1 năm, thời gian đóng tại mỗi cung ăn 1 số \ntoán. \n- Dương cục khởi cung Kiền, thuận hành theo thứ tự: Kiền (1) \n- Ly (2) - Cần (3) - Chận (4) - Trung cung (5) - Đoài (6) - Khôn (7) - Khảm \n(8) - Tốn (9). \n- Âm cục khởi cung Tốn, nghịch hành theo thứ tự: Tốn (9) - Khảm \n(8) - Khôn (7) - Đoài (6) - Trung cung (5) - chấn (4) - Cấn (3) - Ly (2) - \nKiền (1). \nb) Cách toán an sao \nDùng vòng Kỷ Dư chia 9, số dư < 9 dùng để an sao. \nc) Ví dụ: tính và an sao Phi Điểu năm 2014 - Giáp Ngọ. \nTa đã có vòng Kỷ Dư năm 2014 là 331. Lấy 331 : 9 = 36 dư 7. \nNhư vậy năm 2014, theo thứ tự kinh hành của dương cục khởi từ \ncung Kiền thuận hành thì Phi Điểu đóng ở cung Khôn. \n7. Năm Hành (Ngũ Hành) \n\n=== PAGE 24 ===\nNgũ Hành tức là năm Tướng, năm Thần tinh đại diện cho 5 loại khí Ngũ \nhành (Kim - Mộc - Thủy - Hỏa - Thổ). Thái Ất binh pháp xét phương \nvị và tình trạng: Vượng, Tướng, Hưu, Tù, Tử của Ngũ hành để nhận rõ \nthêm khí lực của hai bên chủ khách. \n- Thái Ất: chính khí thuộc hành Mộc, vượng vào mùa Xuân (Đông \nphương). \n- Thủy Kích: chính khí thuộc hành Hỏa, vượng vào mùa Hạ (Nam \nphương). \n- Văn Xương: chính khí thuộc hành Thổ, vượng vào tứ quý (Thn, Tuất, \nSửu, Mùi). \n- Chủ Đại Tướng: chính khí thuộc hành Kim, vượng vào mùa Thu (Tây \nphương). \n- Khách Đại Tướng: chính khí thuộc hành Thủy, vượng vào mùa Đông \n(Bắc phương). \na) Chu kỳ kinh hành \nTiểu chu kỳ của Ngũ hành là 5 số toán, kinh hành qua 5 cung chính \ncủa Thái Ất: \n- Nếu dương cục thì lấy thêm cung Khảm thuận hành theo thứ tự: \nKiền (1) - Khảm - Cấn (3) - Tốn (9) - Khôn (7). \n- Nếu âm cục thì lấy thêm cung Ly nghịch hành theo thứ tự: Tốn (9) \n- Ly (2) - Khôn (7) - Kiền (1) - Cấn (3). \nb) Cách toán an sao \nDùng vòng Kỷ Dư chia 5, số dư < 5 dùng để an sao. \nc) Ví dụ: tính và an sao Ngũ Hành năm 2014 - Giáp Ngọ. \nTa đã có vòng Kỷ Dư năm 2014 là 331. Lấy 331 : 5 = 66 dư 1. \nNhư vậy năm 2014, theo thứ tự kinh hành của dương cục khởi từ \n\n=== PAGE 25 ===\ncung Kiền thuận hành thì Ngũ hành đóng ở tại cung Kiền. \n8. Tam Phong \na) Chu kỳ kinh hành \nTiểu chu kỳ của Tam Phong Thái Ât là 9 số toán, kinh hành qua 9 \ncung chính của Thái Át. \n- Dương cục khởi từ cung Cần (3), thuận hành theo thứ tự: 3 - 7-2 - \n6-1-5-9-4-8. \n- Âm cục khởi từ cung Khôn (7), nghịch hành theo thứ tự: 7 - 3-8 - \n4-9-5-1-6-2. \nb) Cách toán an sao \nDùng vòng Kỳ Dư chia 9, số dư < 9 dùng để an sao. \nc) Ví dụ: tính và an sao Tam Phong năm 2014 - Giáp Ngọ. \nTa đã có vòng Kỷ Dư năm 2014 là 331. Lấy 331 : 9 = 36 dư 7. \nNhư vậy năm 2014, theo thứ tự kinh hành của dương cục khởi từ \ncung Cấn thuận hành thì Tam Phong đóng ở cung 9 (Tốn). \n \nNgũ Phong \na) Chu kỳ kinh hành \nTiểu chu kỳ của Tam Phong Thái Át là 9 số toán, kinh hành qua 9 \ncung chính của Thái Ất. \n- Dương cục khởi từ cung Kiền (1), thuận hành theo thứ tự:1 - 3-5 - \n7-9-2-4-6-8. \n- Âm cục khởi từ cung Khôn (7), nghịch hành theo thứ tự: 7- 3-8 - \n4-9-5-1-6-2. \nb) Cách toán an sao \nDùng vòng Kỷ Dư chia 9, số dư < 9 dùng để an sao. \n\n=== PAGE 26 ===\nc) Ví dụ: tính và an sao Ngũ Phong năm 2014 - Giáp Ngọ. \nTa đã có vòng Kỷ Dư 2014 là 331. Lấy 331 : 9 = 36 dư 7. \nNhư vậy năm 2014, theo thứ tự kinh hành của dương cục khởi từ cung \nKiền thuận hành thì Ngũ Phong đóng ở cung 4 (Chấn). \n10. Bát Phong \na) Chu kỳ kinh hành \nTiểu chu kỳ của Bát Phong là 9 số toán, kinh hành qua 9 cung chính \ncủa Thái Ất. \n- Dương cục khởi từ cung 2 (Ly), thuận hành theo thứ tự: 2 - 3 - 4- 5 \n-6-7-8-9 - 1. \n- Âm cục khởi từ cung 8 (Khảm), nghịch hành theo thứ tự: 8 - 7 - 6 \n-5-4-3-2-1-9. \nb) Cách toán an sao \nDùng vòng Kỷ Dư chia 9, số dư < 9 dùng để an sao. \nc) Ví dụ: tính và an sao Bát Phong năm 2014 - Giáp Ngọ. \nTa đã có vòng Kỷ Dư năm 2014 là 331. Lấy 331 : 9 = 36 dư 7. \nNhư vậy năm 2014, theo thứ tự kinh hành của dương cục khởi từ \ncung 2 (Ly) thuận hành thì Bát Phong đóng ở cung 8 (Khảm). \nNhận xét về các sao: Phi điểu, Tam Phong, Ngũ Phong, Bát Phong trong \nThập Tinh Các Điển. Các sao này đều có tiểu chu kỳ là 9 số toán và kinh \nhành qua 9 cung chính trong bầu trời Thái Ất. Cách toán an sao cũng \ngiống nhau, nhưng cung khởi điểm khác nhau và quy luật vận hành khác \nnhau, nên đường bay kinh hành là khác nhau. \n \nTHẦN TINH DÙNG CHO BINH PHÁP \nNgoài các Tướng, Thần tinh dùng chung cho Tứ Kế, các Thần tinh dùng \n\n=== PAGE 27 ===\ncho việc dự báo thời tiết khí hậu, trong binh pháp còn tính thêm một số \ncác Thần tinh sau: \n1. Thanh Long Thái Tuế \na) Biểu tượng và nghĩa lý \nThanh Long Thái Tuế là Thần tinh giữ cờ xanh hiệu lệnh của Thái Tuế, dự \nbáo về tình trạng thời tiết khí hậu phục vụ cho việc bình bị. \nb) Quy luật vận hành \nMột vòng chu kỳ của Thanh Long là 12 số toán, mỗi cung đóng 1 số \ntoán, khởi từ cung Hợi thuận theo 12 Chi thân. \nc) Cách tính \nDùng vòng Kỷ Dư chia 60, số dư < 60 lại chia tiếp 12, kết quả lấy số \ndư để an sao. \nVí dụ: năm 2014 - Giáp Ngọ, vòng Ký Dư 331 \nBước 1: lấy 331 : 60 = 55 dư 1, số dư 1 < 12 nên dùng 1 để an sao Bước 2: \nan sao, theo thứ tự khởi thuận từ cung Hợi thì năm 2014 - \nGiáp Ngọ, Thanh Long đóng tại cung Hợi. \n2. Khí Xích Kỳ \na) Biểu tượng và nghĩa lý \nXích Kỳ là Thần khí giữ cờ đỏ, báo hiệu thời tiết khí hậu bất thường \nvà bất lợi cho việc dụng bình. \nb) Quy luật vận hành \nXích Kỳ chỉ đóng ở 4 cung tứ mạnh là Dần - Thân - Tị - Hợi, khởi từ cung \nHợi. Một vòng chu kỳ là 4 số toán, tại mỗi cung lưu 1 số toán. \nc) Cách tính \nDùng vòng Kỷ Dư cộng thêm 1, đem chia 40, số dư < 40 lại chia tiếp cho \n4. Kết quả có được dùng số dư để an sao. \n\n=== PAGE 28 ===\nHắc Kỳ (Thái Âm) \na) Biểu tượng và nghĩa lý \nHắc kỳ là Thần tinh giữ cờ báo hiệu của Hậu Phi, thông báo thông tin \ncho chiến trường, báo hiệu khí hậu bất lợi cho việc dụng binh. \nb) Quy luật vận hành \nMột chu kỳ của Hắc kỳ là 36 số toán, khởi từ cung Hợi, nghịch hành \nqua 12 Chi thần, tại mỗi cung đóng 3 số toán (12 x 3 = 36). \nc) Cách tính \nDùng vòng Kỷ Dư cộng thêm 25, kết quả có được chia 36, số dư < 36 lại \nchia tiếp cho 3. Kết quả, số thành là số cung Hắc kỳ đã vận hành qua, số \ndư là thời gian đã vào và đóng ở cung sở tại. \nVi dụ: năm 2014 - Giáp Ngọ, vòng Kỷ Dư là 331. Bước 1: (lấy 331 \n+ 25) : 36 = 9 dư 32 \nBước 2: lấy 32 : 3 = 10 dư 2 \nBước 3: an sao, Hắc kỳ đã vào cung thứ 11 được 2 năm theo thứ tự \nkhởi nghịch từ cung Hợi đến cung Sửu là vừa đủ 11 số toán. \nKết luận: năm 2014 - Giáp Ngọ, Hắc kỳ đóng tại cung Sửu. \n \nPHÉP CỬU TINH TRỰC PHÙ \nCửu Tinh Trực Phù là 9 sao giữ việc lành dữ ở các cung, mà các cung lại \ntương ứng với các phận dã nên thông qua tính chất của tinh tượng, căn \ncứ vào Ngũ hành sinh vượng để xem xét và suy lường. Cửu Tinh luân \nphiên qua 9 cung chính của Thái Ất, 10 năm dịch chuyển 1 lần, 1 vòng \nluân phiên là 90 năm (9 x 10 = 90). \n1. Phép Cửu Tinh Trực Phù liên hệ với Kỳ Môn Độn Giáp Thức. \nĐộn Giáp tức là đem Giáp giấu đi ần đi, lấy Ất - Bính - Đinh làm Tam kỳ, \n\n=== PAGE 29 ===\ntrong đó Ất là Nhật kỳ thuộc Thái dương, Bính là Nguyệt kỳ thuộc Thái \nâm, Đinh là Tinh kỳ thuộc các tinh tú. Các Can khác Mậu, Kỷ, Canh, Tân \nNhâm, Quý làm lục nghi là nơi can Giáp ẩn độn. \nPhép Kỳ Môn Độn Giáp lấy vòng chu kỳ 60 ứng với vòng Lục Thập Hoa \nGiáp nên có 6 tuần Giáp, vì thế cung có 6 tuần Át, 6 tuần Bính, 6 tuần \nĐinh, 6 tuần Mậu, 6 tuần Kỷ, 6 tuần Canh, 6 tuần Tân, 6 tuần Nhâm, 6 \ntuần Quý. \n6 Giáp ẩn độn theo 6 tuần như sau: \ntuần giáp tý : giáp độn ở mậu \ngiáp tuất - động ở kỷ \ngiáp thân - độn ở canh \ngiáp ngọ- động ở tân \ngiáp thìn độn ở nhâm \ngiáp dần độn giáp ở quý. \n+​ bảng chỉ định các tinh tượng phối với 9 can ( riêng can giáp \nẩn nên gọi là độn giáp ) \nthứ tự 1: thiên bồng - phối can Lục Mậu - biệt số 1.​\n2 -thiên nhuế - lục kỷ-2 \n3- thiên xung - lục canh -3 \n4- thiên phụ - lục tân - 4 \n5 - thiên cầm- lục nhâm - 5 \n6 thiên tâm - lục quý - 6 \n7 - thiên trụ- lục đinh - 7 \n8 - thiên nhậm - lục bính - 8 \n9 thiên ương - lục ất  - 9. \n \n\n=== PAGE 30 ===\na) Cách tính \nDùng tích niên Thái Ât của năm cầu việc chia cho vòng lớn 900, \nsố dư chia tiếp 90, số dư < 90 chia tiếp 10, khởi từ Thiên Bồng \nchuyển xuôi theo 9 cung, (cũng có thể dùng vòng Kỷ Dư để \ntoán). \nVí dụ 1: năm Đinh Mão 1987, có vòng Kỳ Dư 304. Bước 1: lấy 304 : \n90 = 3 du 34 \nBước 2: lấy 34 : 10 = 3 dư 4 \nVậy là Trực Phù năm 1987 là sao thứ 4 (Thiên Phụ). Để an các sao \ntrong vòng Cửu Tinh vào đúng cung vị của nó, ta xét năm Đinh \nMão 1987 thuộc tuần lục Đinh mang biệt số 7. Lấy Trực Phù là sao \nThiên Phụ gia vào cung mang biệt số 7 thay cho Thiên Trụ theo \nthứ tự, các sao sẽ được an vào các cung có biệt số tương ứng \nnhư sau: Thiên Phụ (7) - Thiên Cầm \n(8) - Thiên Tâm (9) - Thiên Trụ (1) - Thiên Nhậm (2) - Thiên Ương 3) \n- Thiên Bồng (4) - Thiên Nhuế (5) - Thiên Xung (6). \nVí dụ 2: toán và an vòng Cửu Tinh Trực Phù năm 2025 - Ât Tị có \nvòng \nKỷ Dư 342. \nBước 1: lấy 342 : 90 = ... dư 72 \nBước 2: lấy 72 : 10 = 7 dư 2 \nVậy sao Trực Phù của năm 2025 là sao Thiên Nhậm. \nNăm Ất Tị thuộc tuần Giáp Thìn, lục Ất là sao Thiên Ương mang \nbiệt số 9. Lấy Thiên Trụ gia vào cung mang biệt số 9 (Thiên Ương), \nthứ tự sắp xếp của yng Cửu Tinh Trực Phù sẽ như sau: Thiên \nNhậm (9) - Thiên Ương \n\n=== PAGE 31 ===\n(1) - Thiên Bồng (2) - Thiên Nhuế (3) - Thiên Xung (4) - Thiên Phụ \n(5) - Thiên Cầm (6) - Thiên Tâm (7) - Thiên Trụ (8). \n \nPHÉP TÍNH VĂN XƯƠNG CỬU TINH GIỮ PHẬN DÃ TRỰC SỰ: \n-​ Phép tính văn xương cửu tinh là dựa vào phận dã văn xương \ncửu tinh đóng tại thời điểm lập sa bàn để suy lường họa \nphúc. 9 châu phối 10 can và 9 cung Thái ất theo thứ tự sau:​\nthứ tự 1- văn xương - phối cung càn- can nhâm - dực châu. \n2- huyền phượng - ly - đinh - kinh châu \n3 - Minh Duy - cấn - giáp - thanh châu  \n4- âm đức - chấn -ất - từ châu  \n5 chiêu dao- trung cung - mậu và kỷ - dự châu  \n6 hoa minh - đoài- tân - ung châu  \n7 huyền vũ - khôn - canh- lương châu  \n8 - huyền minh - khảm- quý - duyện châu  \n9 cưu minh - tốn - bính - dương châu \n \nQuy luật vận hành \nVăn Xương khởi từ cung Kiền thuận theo thứ tự 9 cung, tại \nmỗi cung \ntrực sự 30 năm, 1 vòng luân lưu là 270 năm (9 x 30 = 270). \n4. Cách tính \nDùng tích niên Thái Ất của năm cầu việc chia 270, số dư < \n270 chia \ntiếp 30. \nKết quả số thành và số dư để sắp xếp Cửu Tinh giữ phận dã \n\n=== PAGE 32 ===\ntrực sự. \nVí dụ: năm Đinh Mão năm 1987 có tích niên Thái Ất \n10.155.904 Bước 1: lấy 10.155.904 : 270 = ... dư 104 \nBước 2: lấy \n104 : 30= 5 dư 4 \nNăm Đinh Mão thuộc tuần Giáp Tý, Can Đinh, Thần Lục Đinh \nlà Huyền Phượng, phối với cung biệt số 2 (Ly). Năm 1987, Cửu \nTinh giữ phận dã trực sự toán được là Thần Tinh thứ 6, tức \nThần Hoa Minh. \nNay gia trực sự vào Can Đinh, tức lấy cung khởi Hoa Minh tại \ncung \nLy (2), thứ tự của Cửu Tinh giữ phận dã trực sự sắp xếp theo \nthứ tự: \nHoa Minh (2) - Huyền Vũ (3) - Huyền Minh (4) - Cưu Minh (5) \n- Văn Xương (6) - Huyền Phượng (7) - Minh Duy (8) - Âm Đức \n(9) - Chiêu Dao (1). \nTừ biệt số cung Cửu Tinh đóng, có thể suy ra phận dã mà \nVăn Xương \nCửu Tinh trực sự. \n5. Luận giải về Văn Xương Cửu Tinh giữ phận dã trực sự \n- Văn Xương vào Giáp - Ất thì Thanh Châu và Dự Châu xảy ra \nnhiễu tai họa: sâm to gió lớn, việc thô mộc nặng nê, tật bệnh. \nPhép tính Kê Năm hay Kê Tháng ứng với phép toán trên thì \nhọa càng nặng: mưa to gió lớn, lụt lội tràn lan. \n- Văn Xương vào Bính - Đinh thì Kinh Châu và Thương Châu \nhạn hán, hỏa hoạn, khẩu thiệt yêu ngôn. Phép Kể Ngày, Kể \n\n=== PAGE 33 ===\nTháng ứng với toán thì họa lại càng nặng. \n- Văn Xương vào Mậu - Kỷ thì Tượng Châu xảy ra việc thổ \ncông nặng nề, mùa màng thất thu, chết chóc. Phép Kể Năm, \nTháng ứng với toán thì họa càng nặng: động đất, lũ lụt, dân \nchúng bất an. \n- Văn Xương vào Canh - Tân ứng với Lương Châu + Ích Châu \nsẽ có nạn binh đao, trộm cướp, chết chóc. Kế Năm, Kể \nTháng gặp lại càng nặng: đạo tặc hoành hành cướp phá. \n- Văn Xương vào Nhâm - Quý thì Dực Châu và U Châu mưa \ndầm, nước lớn, Hậu Phi nội bộ không yên. \nCác phận dã trên, nếu Văn Xương trực sự hội cùng Thái Ất, \nThái Ất Kể Năm lại gặp các cách thức: Ép, Bách, Kích, Hiệp ... \nthì họa đã nặng càng thêm nặng, tai họa xảy ra ở khắp nơi, \nnếu không gặp các cách thức kể trên thì họa có thể coi là \nnhỏ. \n \nE/ PHÉP TÍNH CỬU TINH QUÝ THẦN GIỮ PHẬN DÃ TRỰC SỰ \nPhép Cửu Tinh Quý Thần là phép toán 9 sao quý giữ việc ở 9 \ncung Thái Ất, gồm 9 sao: Thái Nhất - Thiên Hoàng - Thái Âm - \nHàm Trì - Thanh Long - Thiên Phù - Chiêu Dao - Hiên Viên - \nNhiếp Đề. \n \n1. Quy luật vận hành \nCửu Tinh Quý Thần vận hành luân phiên giữ việc ở 9 cung \nThái Ất, thời gian đóng tại mỗi cung là 1 năm, vòng tiểu chu \nkỳ là 9 năm. Nguyên tắc sắp xếp Quý Thần là lấy Quý Thần \n\n=== PAGE 34 ===\nlàm trực sự phi vào ngự ở Trung cung, Thân tinh đứng sau \nbay ra theo thứ tự nhập vào các cung: Kiền - Đoài - Cấn - Ly \n- Khảm - Khôn - Chấn - Tốn. \n2. Thứ tự các sao khi chưa chuyển dịch theo bảng sau: \nTốn (4) Thiên Hoàng \nLy (9) Thiên Phù \nKhôn (2) Hàm Trì \nChấn (3) Thái Âm \nTrung Cung (5) Thái Nhất \nĐoài (7) Hiên Viên \nCấn (8) Chiêu Dao \nKhảm (1)Thanh Long \nKiền (6)Nhiếp Đề \n \n Cách tính: \nDùng vòng Kỷ Dư cộng thêm 3 toán doanh sai, kết quả chia \ncho 9, số \ndư < 9 dùng để sắp xếp vòng Cửu Tinh. \nVí dụ: năm 2017- Đinh Dậu có vòng Kỷ Dư dư 334 Bước 1: lấy \n334 +3 = 337 \nBước 2: lấy 337 : 9 = 37 dư 4 \nTheo thứ tự thì sao thứ 4 là Hàm Trì lấy làm Quý Thần phi \nnhập vào Trung cung, ta có bảng sắp xếp vòng Cửu Tinh \nQuý Thần năm 2017 như sau: \n \nTốn (4) Thanh Long \n\n=== PAGE 35 ===\nLy (9) Nhiếp Đề \nKhôn (2) Chiêu Dao \nChấn (3) Thiên Phù \nTrung Cung (5) Hàm Trì \nĐoài (7) Thiên Hoàng \nCấn (8) Thái Nhất \nKhảm (1) Hiên Viên \nKiền (6) Thái Âm \nLuận giải Cửu Tinh Quý Thần \nGọi là vòng Cửu Tinh Quý Thần nhưng trong 9 sao có Thần \nsao cát, có Thần sao hung. Nguyên tắc để luận giải là dựa \nvào tính thiện ác Cửu Tinh phối hợp với các Thần tinh tại \ncung thần để luận. \na) Luận về Thái Nhất \nThái Nhất là Thần tinh tốt lành, may mắn, mặc dù là Quý Thần \nbậc hât nhưng nêu vào cung nào mà gặp Đại Du và Tứ Thân \nthì vân xày r oa: nước dâng, sông tắc, vỡ đê, mưa dầm dề, \ntổn hại mùa màng, khí trò độc địa, dân chúng sinh bệnh tật. \n- Thái Nhất ở cung Kiền gặp Đại Du hoặc Tứ Thần thì băng \ntuyết, mưa lạnh giá hại cho đời sống con người, việc thổ \ncông vất vả. \n- Thái Nhất ở cung Khảm gặp Đại Du hoặc Tứ Thần thì mưa \nrơi, tuyết lạnh, nước sông lên cao gây lụt lội. \n- Thái Nhất ở cung Cấn gặp Đại Du hoặc Tứ Thần thì thủy thổ \nphát sinh bệnh tật. \n- Thái Nhất ở cung Chấn gặp Đại Du hoặc Tứ Thần thì lúa \n\n=== PAGE 36 ===\nngô, mùa màng bị côn trùng phá hoại. \n \n- Thái Nhất ở cung Tốn gặp Đại Du hoặc Tứ Thần thì kẻ dưới \nchuyên quyền, việc thổ công nặng nhọc, mưa nhiều hại mùa \nmàng. \n- Thái Nhất ở cung Ly gặp Đại Du hoặc Tứ Thần thì sưu cao \nthuế nặng, hạn hán, sét đánh, cháy rừng. \n- Thái Nhất ở cung Khôn gặp Đại Du hoặc Tứ Thần thì nước \nto, ứng vào tháng 6 - 7 thì hạn chế việc binh. \n- Thái Nhất ở cung Đoài gặp Đại Du hoặc Tứ Thần thì công \nviệc tạp nhạp, nước dâng, nội loạn. \n \nRiêng ở 2 cung Sửu - Mùi Thái Át Kể Tháng mà toán Thái \nNhất gặp các cách kể trên, thì tại phận dã Vua chúa hoặc \ncác bậc quyền quý có sự chẳng lành. \nb) Luận về Nhiếp Đề \n- Nhiếp Đề đóng ở cung nào thì ở đó, năm ấy gió sương lạnh \nlẽo, bệnh tật phát sinh (nhất là bệnh thận và đường ruột). \n- Nhiếp Đề hợp với Tiểu Du và Đại Du thì dịch tả, binh lính làm \ncàn, kỷ luật lỏng lẻo, xảy ra nạn nước lửa. \n- Nhiếp Đề hợp với Thái Ất ở 4 cung Khôn - Chấn - Đoài - \nKiền thì thời tiết thất thường, dân chúng suy kiệt, thóc gạo \nhiếm. \n- Nhiếp Đề hợp ở 4 cung Tốn - Cấn - Khảm - Ly thì phát sinh \ndịch bệnh, xảy ra nhiều cái chết bất thường. \nc) Luận về Hiên Viên \n\n=== PAGE 37 ===\n- Hiên Viên đến các cung Chấn - Tốn thì muôn vật tốt tươi \n- Hiên Viên nếu gặp Thái Ất thì khí trời ấm áp hài hòa, cỏ cây \nxanh tốt, mùa màng bội thu. \n- Hiên Viên nếu hội với Tứ Thần, Đại Du thì thời tiết nóng lạnh \nthất thường, mùa màng kém thu hoạch, nhiều sấm sét, tệ \nnạn trộm cắp cướp bóc phát sinh. \n- Hiên Viên mùa Xuân đóng ở các cung Cấn - Chấn, mùa Hạ \nở Tốn  \n- Ly, mùa Thu ở Khôn - Đoài, mùa Đông ở Kiền - Khảm thì gió \nto, mùa Xuân thì sấm sét sớm, mùa Thu, Hạ có nhiều sấm sét, \nmùa Đông vẫn còn sấm. \nd) Luận về Chiêu Dao \n- Chiêu Dao vào cung nào thì ở đó năm ấy có gió lớn, rừng \ncây đổ găy, mùa màng thất thu. \n- Chiêu Dao hợp với Tứ Thần và Đại Du thì dân chúng xác xơ \nđói kém, sâu bệnh tàn hại mùa màng, bệnh tật phát sinh, \nđộng đất, hạn hán, chiến loạn. \n- Chiêu Dao vào cung Tốn thì gió nóng, vật cháy bị nướng \nchín. \n- Chiêu Dao vào cung Cấn thì mưa gió liên miên. \n- Chiêu Dao vào cung Ly thì hạn hán, gió nóng. \n- Chiêu Dao vào cung Chấn thì sấm sét nhiều, mưa gây tai \nhại. \nLuận về Chiêu Dao \n- Chiêu Dao vào cung nào thì ở đó năm ấy có gió lớn, rừng \ncây đổ găy, mùa màng thất thu. \n\n=== PAGE 38 ===\n- Chiêu Dao hợp với Tứ Thần và Đại Du thì dân chúng xác xơ \nđói kém, sâu bệnh tàn hại mùa màng, bệnh tật phát sinh, \nđộng đất, hạn hán, chiến loạn. \n- Chiêu Dao vào cung Tốn thì gió nóng, vật cháy bị nướng \nchín. \n- Chiêu Dao vào cung Cấn thì mưa gió liên miên. \n- Chiêu Dao vào cung Ly thì hạn hán, gió nóng. \n- Chiêu Dao vào cung Chấn thì sấm sét nhiều, mưa gây tai \nhại. \ne) Luận về Thiên Phù \n- Thiên Phù vào cung lại hội với Tứ Thân - Đại Du thì dân tình \nkhôn khổ, sưu cao thuế nặng, việc thổ công nặng nhọc, phục \ndịch cho việc binh vất vả, việc nhà nông đình đốn, lúa má sâu \nbệnh. \n- Thiên Phù vào cung Khảm thì đê vỡ, dân bệnh. \n- Thiên Phù vào cung Cấn - Đoài thì sương lạnh, gia súc chết. \n- Thiên Phù vào cung Kiền thì trời lạnh giá, băng tuyết. \n- Thiên Phù vào cung Ly thì hạn hán. \n- Thiên Phù vào cung Tốn thì sấm rền, mua đá, việc nhà nông \nkhó nhọc. \n- Thiên Phù vào Trung cung thì hại cho Hậu Phi, nhất là vào \ncác tháng Sửu, Mùi. \n- Thiên Phù vào cung Chấn thì sương lạnh, mua nhiều, dịch \nbệnh, sâu lúa. \n \n- Thiên Phù vào cung Khôn thì nắng hanh cỏ cháy, mưa \n\n=== PAGE 39 ===\nnhiều, dịch bệnh. \n) Luận về Thanh Long \n- Thanh Long vào cung nào thì cũng thời tiết lạnh buốt, \nsương giá. \n- Thanh Long hội với Tứ Thần, Đại Du, Tiểu Du thì dân chúng \nxiêu liêu, dịch bệnh hoành hành, quân binh mệt mỏi. \n- Thanh Long vào cung Ly thì nước lụt, bình lính mệt mỏi. \n- Thanh Long vào Trung cung nếu là tháng 11 và 12 thì dân \nđói, thời tiết lạnh giá. \nLuận về Hàm Trì \n- Hàm Trì vào cung nào thì cũng sương lạnh, cỏ cháy, lúa khô, \ndân đói, ngoại xâm, nước dâng, bệnh tật, sạt lở núi. \n- Hàm Trì hội với Đại Du, Tiểu Du, Tứ Thần, Thái Át thì có gió \nTây thổi đến mang theo vị mặn, xảy ra nhiều việc tai quái. \nh) Luận về Thái Âm \n- Thái Âm vào cung nào thì ở đó trời trăng mờ mịt, ít sao. \n- Thái Âm hợp với Tứ Thần, Đại Du, Tiểu Du thì Hậu Phi cần \ngiữ chính, Đại Thần chuyên quyền, xây nhiều dinh thự làm \nphiền dân chúng, thời tiết mưa gió trái mùa, vụ mùa thu \nhoạch kém. \ni) Luận về Thiên Hoàng (Thiên Át) \n- Thiên Ất vào cung nào thì ở đó đại hạn, chướng khí nóng, \nngười đau bệnh, côn trùng có cánh hại mùa màng. \n- Thiên Át hội với Tứ Thần, Đại Du, Tiểu Du xảy ra chiến loạn. \n- Thiên Ất ở cung Khảm hội với Tứ Thần, Đại Du, Tiểu Du thì \nsưu cao thuế nặng, lòng dân bất ổn, hỏa hoạn. \n\n=== PAGE 40 ===\n \nLUẬN VỀ SÓ TOÁN THÁI ẤT \n1. Tam Tài toán pháp \nThái Ât Thức có 3 số toán là: Toán Định - Toán Chủ - Toán \nKhách Được xét theo định số của Tam Tài để dự báo cát \nhung. Theo định số thì: số 1 thuộc về nhân, số 5 thuộc về địa, \nsố 10 thuộc về thiên, từ đó xuất hiện cụm từ: Vô thiên, Vô \nđịa, Vô nhân. \na) Toán Vô thiên \nKhi kết quả số Toán Định - Toán Chủ - Toán Khách chỉ ở hàng \nđơn vị \ntừ 1 đến 9, tức là chưa quá 10 thì được gọi là toán Vô thiên. \n \nThái Át Kế Năm gặp số toán Vô thiên, lại hội với cáo Cách bất \nthường: Yếm. Kích, Tù, Ép, Đối, Cách... thì thiên tượng khí hậu \nnăm ấy xáy ra dại biến khác thường: mũt trời, mặt trăng, tính \ntú không sáng, sấm sét, giông băo, mum lớn, mua đá, nắng \nnóng, băng giá.... tác động tiêu cực rất lớn đến đời sống con \nngười. \nb) Toán Vô địa \nKhi kết quá số Toán Định - Toán Chủ - Toán Khách có hàng \nđơn vị không tới được số 5 thì được gọi là toán Vô địa. Ví như \ncác số : 1,2, 3, 4 hoặc 11, 12, 13, 14 hoặc 21, 22, 23, 24... đều là \ncác số toán Vô địa. \nThái Át Kể Năm gặp số toán Vô địa lại hội với các Cách bất \nthường như: Yếm, Kích, Tù, Ép, Đối, Cách ... thì địa tượng năm \n\n=== PAGE 41 ===\nấy xảy ra nhiều biến động lạ: động đất, núi lớ, lũ lụt, sóng \nthần, hạn hán, cháy rừng, nước biển dâng... gây tác hại rất \nlớn, ảnh hưởng đến đời sống dân sinh. \nc) Toán Vô nhân \nKhi kết quả số Toán Định - Toán Chủ - Toán Khách có hàng \nđơn vị bằng 0 gọi là số toán Vô nhân. Ví như các số : 10, 20, \n30, 40 đều là số toán Vô nhân. \nThái Ất Kể năm gặp số toán Vô nhân lại hội với các Cách bất \nthường như: Yếm, Kích, Tù, Ép, Đối, Cách ... thì xã hội con \nngười tất xảy ra nhiều biến động tiêu cực: luân thường bị đảo \nlộn, đạo đức suy đồi, kỷ cương rối loạn, con người trờ lên \nđiên đảo, gian dối, trộm cướp, nổi loạn, ly tán, lưu vong... \nNếu đúng vào kỳ lý nhân của Thái Ất là điềm báo có những \nbậc kỳ \ntài, Thánh Nhân, Thiên Tử xuất hiện để cứu đời. \n \nTrường hợp đặc biệt Tam Tài 3 toán đều Vô Thiên - Vô Địa - \nVô Nhân. \nThánh Nhân xưa chiêm nghiệm: Thái Ất Kể Năm gặp trường \nhợp đặc biệt 3 toán Tam Tài đều Vô thiên - Vô địa - Vô nhân, \nlại hội thêm với các Cách bất thường: Yếm, Kích, Tù, Ép, Đối, \nCách... thì định rằng: \n \n- Năm ấy vào chính kỳ Thiên - Địa - Nhân tối hung ương, đại \nhọa và tai ách lớn tất xảy ra: chiến tranh, loạn lạc, lưu vong, \ndịch bệnh, mất mùa, đói kém, thời tiết khắc nghiệt... \n\n=== PAGE 42 ===\n- Bầu trời tất sẽ xuất hiện Sao Chổi, báo hiệu tai họa xảy ra \nliên miên. \nNgười xưa cho rằng: sao Chổi là ngọn đuốc, cái lồng lửa của \ntrời, là loại sao xếp vào hàng yêu quái. Qua quan sát sao Chổi \nthấy hình dạng biến hóa vô cùng: to, nhỏ, dài, ngăn, tỏ, mờ ..., \nmàu sắc cũng không giống nhau. Căn cứ vào mùa trong \nnăm, phương vị sao Chổi xuất hiện, hình dáng và màu sắc \ncủa nó để đặt tên. \nSách \"Binh Thư yếu lược\" của Đức Quốc Công Tiết Chế Hưng \nĐạo \nĐại Vương ghi chép về sao Chổi như sau: \n- Sao Chổi xuất hiện hướng Đông gọi là Tuế Tinh. \n- Sao Chổi xuất hiện mùa Xuân gọi là Nhiếp Đề. \n- Sao Chổi xuất hiện mùa Hạ gọi là Tùng Hoa. \n- Sao Chổi xuất hiện mùa Thu gọi là Ứng Tinh. \n- Sao Chổi xuất hiện mùa Đông gọi là Kỷ Tinh. \n* Sao Chổi đuôi có hình nhọn như mũi giáo gọi là Thiên Ngộ, \nThiên Cánh, Giác Tinh. \n* Sao Chổi có đuôi hình cong, màu đỏ gọi là Xuy Vưu, Kỳ \nĐảm Tinh, Mao Đầu Tinh. \n* Sao Chổi có đuôi giống như bó đưốc màu đỏ, gần sát đất \ngọi là Nguyệt Hoa. \n* Sao Chổi có đuôi giống như 2 mũi nhọn, màu trắng mọc \ngần sát đất gọi là Tư Nguy. Giống sao Thái Bạch và cũng \nthường xuất hiện hướng Tây. \n* Sao Chổi to lớn hình dài, đuôi dài không có sừng nhọn, có \n\n=== PAGE 43 ===\nđèo thêm 3 sao ở đầu, lúc ở cao khi xuống thấp, gọi là Chiêu \nMinh (hay Chiêu Dao). \n* Sao Chổi giống hình cây kiếm dài, lại mọc phía Tây, có khi lại \ncong như cánh cung đang giương gọi là Trương Cung Tinh, \nThương Ngân Tình, Thần Hoa Tinh. \n* Sao Chối mọc phía Đông cách mặt đất 7 thước hình giống \nnhư mũi thuổng chĩa ra, nhn giống như cái tán, mũi dài nhọn \nló ra, màu sắc có thể là đỏ, xanh, gọi là Năm Tán. \n* Sao Chôi hình như tâm vải dính vào da trời gọi là Trương \nCánh, đôi khi giống như sợi chỉ dài có thể là 2-3 sợi gọi là Đối \nTinh. \n* Sao Chổi mọc cách mặt đất 6 thước màu đỏ, chiếu sáng ở \nhướng Nam gọi là Thiên Tặc. \n* Sao chổi xuất hiện giống như Sao Băng, hình như mũi tên, \nmàu xanh đen chạy xét như con rắn có sừng gọi là Cuống \nThi. Từ trên chạy xét xuống gọi là Hưu Tinh, từ dưới chạy xét \nlên là Phi Tinh, sao lớn gọi là Bôn Tinh. Cái tên Bật Tinh cũng \nlà tên gọi Sao Chổi. \n* Sao Chổi ngắm bên cạnh có hình giống như con chó chạy, \ntrên nhọn dưới tròn, xẹt xuống như ánh lửa đổ, có khí màu \ntrắng, phát ra tiếng kêu. Có chung tên gọi là Hưu Tinh, Phi \nTinh và Bôn Tinh. Thái Ất gọi sao này là Phi Phù, sách binh \npháp gọi sao Chối ở cách thức này là Thiên Cẩu hoặc Phao \nGiảng Tình. \n2. Bàn về số toán âm dương hòa hay bất hòa \nBốn thời khí phân thành 12 Chi Thần phối với 9 cung tạo nên \n\n=== PAGE 44 ===\nsố toán âm dương của Thái Ất thức, nguyên khí thuận \nchuyền, thống hội để Thần tinh Thái Ất kinh hành phân định 2 \nphần cương nhu, âm dương tương phối chủ khách phân \nđịnh. \na) Đường nguyên khí \nTrong thiên địa, nguyên khí thuận chuyển theo quy luật của \nâm dương tương giao, Càn Khôn đắp đối, dương trưởng - \nâm tiêu, âm trưởng - dương tiêu. Trong dương luôn có âm, \ntrong âm luôn có dương. \nThuyết Tịch Quái 12 tháng chỉ ra: 12 quẻ tiêu tức gồm có: \nPhục - Lâm - Thái - Đại Tráng - Quải - Càn - Cấu - Độn - Bĩ - \nQuan - Bác - Khôn. \n \ntừ Phục đến Càn là quá trình dương khí từng bước tăng \nthêm, âm khí giảm dần, về thời điểm tương ứng các tháng 11, \n12, 1, 2, 3,4. \nTừ Càn đến Khôn là thời kỳ âm trưởng dương tiêu, khí âm \ntăng dần Và khí dương từng bước giảm dần, về thời tương \nứng với các tháng 5, 6, 7,8,9,10 \nTrong một năm nguyên khi thuận hành theo vòng mà âm \ndương phối ngẫu vào các cung. 12 quẻ Tịch Quái ứng với 72 \nhào, tượng trưng cho sự biến đối của 24 tiết khi và 72 hậu. \nMà 12 Tịch Quái giải thích thuyết âm dương lợi trùng với 8 \ncung phối biệt số \nTừ đó phân định âm dương theo lý: phân định ra dương trợ \nchủ, âm trợ khách. \n\n=== PAGE 45 ===\n \nLuận về số toán âm dương hòa hay bất hòa \nTrương Lương nói rằng: \"Âm dương hòa hay bất hòa chính là \ndo sự \nphối hợp giữa Thái Ất và số của Nhị Mục\". \n* Toán Thái Ất hòa là khi: \n- Thái ất đóng ở các cung dương: 8, 3. 4, 9 mà toán được số \nchẵn . \n- Thái ất đóng ở các cung âm: 2, 7, 6, 1 mà toán được số lẻ . \nHai trường hợp trên đều là toán Thái Ất hòa. \n* Toán Thái Ất bất hòa là khi: \n- Thái Ất đóng ở cung dương: 8, 3, 4, 9 mà toán được số lẻ . \n- Thái Át đóng ở các cung âm: 2, 7, 6, 1 mà toán được số chẵn \n. \nHai trường hợp trên đều là toán Thái Ât bất hòa. \nVậy nên các con số: \n- 3, 9 là số lẻ thuộc dương, nếu lại phối vào cung dương thì \ngọi là số toán Thuần Dương. \n- Nếu số 3, 9 trùng điệp thành số 33, 39 và phối ở cung \ndương thì gọi là số Trùng Dương. \n- 2, 6 là số chẵn thuộc âm, nếu lại phối ở cung âm thì gọi là \nsố toán Thuần Âm. \n- Nếu số 2, 6 trùng điệp thành số 22, 26 và phối ở cung âm \nthì gọi là số Trùng Âm. \n- 1, 7 là số lẻ thuộc dương, nếu phối hợp ở các cung âm thì \ngọi là số toán Tạp Dương. \n\n=== PAGE 46 ===\n- Nếu số 1, 7 tự trùng lặp thành 11, 17 lại phối ở cung âm thì \ngọi là số toán Trùng Dương trong âm. \n- Trường hợp các số 11, 17 lại phối ở các cùng dương thì gọi \nlà các số Tạp Trùng Dương, như các số : 13, 19, 31, 37 là số \nTạp Trùng Dương. \n- Nếu 2, 8 lại phối hợp ở các cung âm thì gọi là số Tạp Âm. \n- Các số 24, 28 là số Trùng Âm, nếu phối ở các cung âm thì \nsố toán gọi là số Tạp Trùng Âm. \n- Nếu số 24, 28 là số Trùng Âm lại phối ở các cung dương thì \ngọi là số Trùng Âm trong dương. \nToán Nhị Mục hòa là khi: \n- Nhị Mục (Văn Xương - Thủy Kích) đóng tại các cung chính \n(1, 8, 3, 4,9, 2, 7, 6) thuộc dương mà toán được số chẵn \n(ngẫu). \n- Nhị Mục (Văn Xương - Thủy Kích) đóng tại các cung gián \nthần (Sửu, Dần, Thìn, Tị, Mùi, Thân, Tuất, Hợi) thuộc âm mà \ntoán được số lẻ (cơ). \nHai trường hợp trên là toán Nhị Mục hòa. \n* Toán Nhị Mục bất hòa là khi : \n- Nhị Mục đóng ở các cung chính (dương) toán được số lẻ \n(cơ). \n- Nhị Mục đóng ở các cung gián thần (âm) toán được số \nchẵn (ngẫu). \nHai trường hợp trên là toán Nhị Mục bất hòa. \nVậy nên có các con số hòa hay bất hòa như sau: \n- 11, 13, 17, 19, 31, 33, 37, 39 là số dương mà Nhị Mục ở các \n\n=== PAGE 47 ===\ncung chính (thuộc dương) là những số toán Nhị Mục bất hòa. \n- 22, 24, 26, 28 là các số âm mà Nhị Mục ở các cung gián \nthần (thuộc âm) là những số toán Nhị Mục bất hòa. \nThái Ất thức dự báo: toán hòa thì khí thuận, âm dương tương \nhợp, làm nên may mắn tốt lành. Toán bất hòa là khí không \nthuận, âm dương đối lập, thiên địa bất tương giao, vạn sự trái \nvới lẽ tự nhiên, đó là thời của tai ương có cơ hội phát động. \n* Toán Thái Ất và toán Nhị Mục phối kết: \n- Khi Thái Ất và Nhị Mục lại ở cung dương mà số toán là số \nTrùng Dương ví như số toán 33,39; hoặc khi Thái Ất và Nhị \nMục đóng ở các cung âm mà số toán là số Trùng Âm ví như \nsố toán 22, 26 đều gọi là toán Thái Quá. \nThái Ất thức dự báo: toán Thái Quá là thời có hôn quân, bạo \nchúa. \n- Khi Thái Ất và Nhị Mục đóng tại các cung âm mà số toán \nđược lại Thuần Dương, hoặc khi Thái Ất và Nhị Mục đóng ở \ncác cung dương, toán được số toán Thuần Âm đều gọi là số \ntoán Bất Cập. \n \nThái Ất thức dự báo: toán Bất Cập là toán đại hung. Nếu Thái \nÁt và Nhị Mục ở các cung Tuyệt Dương thì tai họa càng hung \nhiểm bội phần. \n- Khi Thái Ất, Nhị Mục đóng tại các cung dương mà toán \nđược các số toán Tạp Trùng Dương ví như 13,19, 31, 37, hoặc \nkhi Thái Ất, Nhị Mục đóng tại các cung âm mà toán được các \nsố Tạp Trùng Âm ví như 24, 28 thì cá hai trường hợp trên đều \n\n=== PAGE 48 ===\ngọi là toán Thứ Hung. \n- Khi Thái Ất, Nhị Mục đóng tại các cung dương toán được \ncác số toán Âm Trùng trong dương 13, 17, hoặc khi Thái Ất, \nNhị Mục đóng tại các cung âm toán được các số toán Dương \nTrùng trong âm 44, 48 thì cả hai trường hợp trên là toán Đại \nHung. \nThái Ất thức dự báo: toán hung tất trong ngoài đều có mưu \nsâu kế \nhiếm sắp sẵn: \nNếu là số toán Trùng Dương là có mưu ở trong. \nNếu là số toán Trùng Âm là có mưu ở ngoài. \nNếu so sánh nặng nhẹ thì đương nặng mà âm nhẹ. \n- Khi Thái Ất, Nhị Mục có các số toán là dương ví như 1, 3 mà \nphối ở cung âm, hoặc khi số toán là âm ví như 4, 8 phối ở \ncung dương, do âm dương phối hợp nên được số toán gọi là \nThượng Hòa, ví như các số 14, 18, 33 là số toán Thượng Hòa. \n- Khi Thái Ất, Nhị Mục ở các cung dương có các số dương 3, \n9 là số lẻ phối hợp, được gọi là số Dương độc lập hoặc khi \nThái Ất, Nhị Mục ở các cung âm mà có các số 2, 6 phối hợp là \nsố chẵn, cũng được gọi là số âm độc lập. Vậy nên các con số \n23, 29, 32 là số Thứ Hòa, \n- Trường hợp số Dương độc lập và số Dương tự hòa phối hợp \nvới các số Âm độc lập và số Âm tự hòa. Sự phối hợp các con \nsố trong trường hợp này được gọi là con số Hạ Hòa. Ví như \nsố 12,16,27, 34, 38 là các con số Hạ Hòa. \nThái Ất thức dự báo: số toán hòa thì cát, bất hòa thì hung. \n\n=== PAGE 49 ===\nBất luận Thái Ất hay Nhị Mục ở cung âm hay dương, nếu \ndương số nhiều thì luôn có \nlợi cho khách, nếu âm số nhiều thì luôn có lợi cho chủ. Đấy \ncũng là căn cứ để xét đến việc chủ khách thắng bại. \n";

export function getMatchingCucKnowledge(donType, cucNum) {
    const isAm = donType && (donType.toLowerCase().includes('âm') || donType.toLowerCase().includes('am'));
    const parts = THAI_AT_144_RAW.split('Đến 72 khối dương.');
    const targetSection = isAm ? parts[0] : (parts[1] || parts[0]);
    const lines = targetSection.split('\n');
    let found = false;
    let resultLines = [];
    
    for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();
        if (line.match(new RegExp('^' + cucNum + '\\.')) || (line === String(cucNum))) {
            found = true;
            resultLines.push(line);
            continue;
        }
        if (found) {
            if (line.match(/^\d+\./) || line.match(/^\d+$/)) {
                break;
            }
            resultLines.push(line);
        }
    }
    
    if (resultLines.length > 0) {
        return (isAm ? '--- KHỐI ÂM ' : '--- KHỐI DƯƠNG ') + cucNum + ' ---\n' + resultLines.join('\n').trim();
    }
    return '';
}
